const investimentos = {
  "Conservador": [
    { produto: "Poupança", minimo: 100, rentabilidade: "6.2%" },
    { produto: "CDB Liquidez Diária", minimo: 1000, rentabilidade: "12.5%" },
    { produto: "Tesouro Selic", minimo: 500, rentabilidade: "13.0%" }
  ],
  "Moderado": [
    { produto: "CDB Prefixado", minimo: 1000, rentabilidade: "14.0%" },
    { produto: "Fundo Multimercado", minimo: 5000, rentabilidade: "16.0%" },
    { produto: "Tesouro IPCA+", minimo: 1000, rentabilidade: "IPCA+6.0%" }
  ],
  "Arrojado": [
    { produto: "Ações ETF", minimo: 500, rentabilidade: "Variável" },
    { produto: "Fundo de Ações", minimo: 10000, rentabilidade: "Variável" },
    { produto: "Criptomoedas", minimo: 100, rentabilidade: "Variável" }
  ]
};

const clientes = $input.first().json.body.clientes;

const resultados = clientes.map(cliente => {
  const opcoes = investimentos[cliente.perfil] || [];
  const listaProdutos = opcoes
    .map(o => `${o.produto} (mínimo R$${o.minimo}, rentabilidade ${o.rentabilidade})`)
    .join(", ");

  const mensagem = `Olá ${cliente.nome}, com base no seu perfil ${cliente.perfil}, recomendamos: ${listaProdutos}.`;

  return {
    json: {
      nome: cliente.nome,
      email: cliente.email,
      perfil: cliente.perfil,
      mensagem: mensagem
    }
  };
});

return resultados;;
